{
  "tool_id": "source_control.rollback_release",
  "service": "checkout-api",
  "environment": "production",
  "rationale": "The Checkout API's p95 latency has increased to 2150 ms in production after the deployment of version v4.17, which is likely due to a misconfiguration in the database connection pool. The migration to orders-client v3 reduced the max_connections and acquire_timeout_ms, leading to connection pool exhaustion and increased latency. Rolling back to the previous version, v4.16, will restore the original database connection pool settings and resolve the latency issue.",
  "citations": [
    "RB-CHK-007 \u00a7Latency regression after a release",
    "RB-CHK-007 \u00a7Rolling back checkout-api"
  ]
}

{
  "status": "mitigated",
  "note": "Checkout API p95 latency elevated due to database connection pool misconfiguration after deploying v4.17. Rolled back to v4.16, latency reduced to 200 ms, below SLO of 400 ms."
}
